  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (eventId.present) {
      map['event_id'] = Variable<int>(eventId.value);
    }
    if (channelId.present) {
      map['channel_id'] = Variable<String>(channelId.value);
    }
    if (node.present) {
      map['node'] = Variable<String>(node.value);
    }
    if (kind.present) {
      map['kind'] = Variable<String>(
        $TypingEventsTable.$converterkind.toSql(kind.value),
      );
    }
    if (startedAt.present) {
      map['started_at'] = Variable<int>(
        $TypingEventsTable.$converterstartedAt.toSql(startedAt.value),
      );
    }
    if (endedAt.present) {
      map['ended_at'] = Variable<int>(
        $TypingEventsTable.$converterendedAt.toSql(endedAt.value),
      );
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('TypingEventsCompanion(')
          ..write('eventId: $eventId, ')
          ..write('channelId: $channelId, ')
          ..write('node: $node, ')
          ..write('kind: $kind, ')
          ..write('startedAt: $startedAt, ')
          ..write('endedAt: $endedAt')
          ..write(')'))
        .toString();
  }
}

