class MessageRow extends DataClass implements Insertable<MessageRow> {
  final String messageId;
  final String channelId;

  /// Sender node id (`NODE-XXXX-XXXX`).
  final String sender;

  /// Receiver node id; null for group/broadcast channels.
  final String? receiver;

  /// Epoch ms; the mesh clock, not necessarily wall time.
  final DateTime timestamp;
  final Uint8List encryptedPayload;

  /// IV/nonce accompanying the payload (can be absent for no-encryption modes).
  final Uint8List? payloadIv;
  final MessageType messageType;
  final MessageStatus status;
  final String? replyTo;
  final bool forwarded;
  final bool edited;
  final bool deleted;
  final int? ttl;
  final PriorityLevel priority;

  /// Message schema version for forward-compatible payload parsing.
  final int version;

  /// Per-channel ordering counter assigned by the origin node.
  final int sequence;

  /// Generator-chosen idempotency key of the client that produced the message.
  final String? clientId;

  /// DTN envelope id that carried this message (outbound only).
  final String? packetId;

  /// Plaintext body kept at rest for local rendering and search. The
  /// authoritative wire representation remains [encryptedPayload]; this
  /// column is the local, device-side content mirror (device-at-rest
  /// encryption belongs to a later phase).
  final String? bodyText;

  /// When the local user read this message (read receipts).
  final DateTime? readAt;

  /// Receipt verification completed for this message.
  final bool verified;

  /// When the receipt chain verified this message (crypto verification).
  final DateTime? verifiedAt;

  /// Local user starred this message.
  final bool starred;

  /// First-arrival index at this node: the local tie-break of the ordering
  /// key (written only on first arrival / compose, never moved).
  final int packetOrder;

  /// How many times the outbox tried to store this message's envelope.
  final int attemptCount;

  /// Reason of the last failure / cancel (outbox bookkeeping).
  final String? lastError;
  const MessageRow({
    required this.messageId,
    required this.channelId,
    required this.sender,
    this.receiver,
    required this.timestamp,
    required this.encryptedPayload,
    this.payloadIv,
    required this.messageType,
    required this.status,
    this.replyTo,
    required this.forwarded,
    required this.edited,
    required this.deleted,
    this.ttl,
    required this.priority,
    required this.version,
    required this.sequence,
    this.clientId,
    this.packetId,
    this.bodyText,
    this.readAt,
    required this.verified,
    this.verifiedAt,
    required this.starred,
    required this.packetOrder,
    required this.attemptCount,
    this.lastError,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['message_id'] = Variable<String>(messageId);
    map['channel_id'] = Variable<String>(channelId);
    map['sender'] = Variable<String>(sender);
    if (!nullToAbsent || receiver != null) {
      map['receiver'] = Variable<String>(receiver);
    }
    {
      map['timestamp'] = Variable<int>(
        $MessagesTable.$convertertimestamp.toSql(timestamp),
      );
    }
    map['encrypted_payload'] = Variable<Uint8List>(encryptedPayload);
    if (!nullToAbsent || payloadIv != null) {
      map['payload_iv'] = Variable<Uint8List>(payloadIv);
    }
    {
      map['message_type'] = Variable<String>(
        $MessagesTable.$convertermessageType.toSql(messageType),
      );
    }
    {
      map['status'] = Variable<String>(
        $MessagesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || replyTo != null) {
      map['reply_to'] = Variable<String>(replyTo);
    }
    map['forwarded'] = Variable<bool>(forwarded);
    map['edited'] = Variable<bool>(edited);
    map['deleted'] = Variable<bool>(deleted);
    if (!nullToAbsent || ttl != null) {
      map['ttl'] = Variable<int>(ttl);
    }
    {
      map['priority'] = Variable<String>(
        $MessagesTable.$converterpriority.toSql(priority),
      );
    }
    map['version'] = Variable<int>(version);
    map['sequence'] = Variable<int>(sequence);
    if (!nullToAbsent || clientId != null) {
      map['client_id'] = Variable<String>(clientId);
    }
    if (!nullToAbsent || packetId != null) {
      map['packet_id'] = Variable<String>(packetId);
    }
    if (!nullToAbsent || bodyText != null) {
      map['body_text'] = Variable<String>(bodyText);
