  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['destination'] = Variable<String>(destination);
    map['next_hop'] = Variable<String>(nextHop);
    map['hop_count'] = Variable<int>(hopCount);
    map['quality'] = Variable<double>(quality);
    {
      map['last_updated'] = Variable<int>(
        $RoutesTable.$converterlastUpdated.toSql(lastUpdated),
      );
    }
    if (!nullToAbsent || expiration != null) {
      map['expiration'] = Variable<int>(
        $RoutesTable.$converterexpiration.toSql(expiration),
      );
    }
    return map;
  }

  RoutesCompanion toCompanion(bool nullToAbsent) {
    return RoutesCompanion(
      destination: Value(destination),
      nextHop: Value(nextHop),
      hopCount: Value(hopCount),
      quality: Value(quality),
      lastUpdated: Value(lastUpdated),
      expiration: expiration == null && nullToAbsent
          ? const Value.absent()
          : Value(expiration),
    );
  }

